/// The top of the root `codeality.yml`, before its jobs. Byte-identical to
/// codeality-dart's: whichever tool creates the file writes it.
let codealityWorkflowHeader = """
    # Generated by codeality-dart init and codeality-swift init. Each job belongs
    # to the tool that wrote it: re-running init adds missing jobs and reports
    # edited ones as conflicts. Call it from a job in your own CI:
    #   uses: ./.github/workflows/codeality.yml
    name: codeality

    on:
      workflow_call:
      workflow_dispatch:

    permissions:
      contents: read

    jobs:

    """
